const email = process.env.NERJA_EMAIL;
const password = process.env.NERJA_PASSWORD;
if (!email || !password) throw new Error('Set NERJA_EMAIL and NERJA_PASSWORD env vars');
return [{ json: { email, password } }];

const r = $json;
if (r.statusCode !== 200) throw new Error('Login failed: ' + r.statusCode);
const setCookie = r.headers && r.headers['set-cookie'];
const cookie = Array.isArray(setCookie) ? setCookie.join('; ') : (setCookie || '');
return [{ json: { cookie, pages: [
  { name: 'Dashboard', url: 'https://dev.nerja.ai/app/dashboard', expectedTitle: 'Dashboard' },
  { name: 'Data Room', url: 'https://dev.nerja.ai/app/data-room', expectedTitle: 'Data room' },
  { name: 'Analytics', url: 'https://dev.nerja.ai/app/analytics', expectedTitle: 'Analytics' },
  { name: 'Leads', url: 'https://dev.nerja.ai/app/leads', expectedTitle: 'Leads' },
  { name: 'Campaigns', url: 'https://dev.nerja.ai/app/campaigns', expectedTitle: 'Campaigns' },
  { name: 'Integrations', url: 'https://dev.nerja.ai/app/integrations', expectedTitle: 'Integrations' },
  { name: 'Plan & Billing', url: 'https://dev.nerja.ai/app/plan-and-billing', expectedTitle: 'Plan' },
  { name: 'Settings', url: 'https://dev.nerja.ai/app/settings', expectedTitle: 'Settings' }
] } }];

const r = $json;
const page = $('Split App Pages').item.json;
const body = typeof r.body === 'string' ? r.body : JSON.stringify(r.body || '');
const statusOk = r.statusCode === 200;
const notLoginPage = !body.includes('Welcome back') && !body.includes('Log in to recover');
const titleMatch = body.includes(page.expectedTitle);
const ok = statusOk && notLoginPage && titleMatch;
return [{ json: { name: page.name, url: page.url, statusCode: r.statusCode, passed: ok, detail: ok ? '✅ ' + page.name + ' loads and is authenticated' : '❌ ' + page.name + ' → ' + r.statusCode + (!notLoginPage ? ' [redirected to login]' : '') + (!titleMatch ? ' [wrong page content]' : '') } }];

const results = $json.results || [];
const passed = results.filter(r => r.passed).length;
const failed = results.filter(r => !r.passed).length;
console.log('\n╔═══════════════════════════════════════╗');
console.log('║  NERJA AI — APP PAGES RESULTS         ║');
console.log('╚═══════════════════════════════════════╝');
results.forEach(r => console.log(r.detail));
console.log('\n→ ' + passed + '/' + results.length + ' passed | ' + failed + ' failed');
return [{ json: { suite: '03 Authenticated App Pages', total: results.length, passed, failed, status: failed === 0 ? 'PASS' : 'FAIL', tests: results, timestamp: new Date().toISOString() } }];
